package dev.bennett.codexmeter;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;

/** Owned AVD only: previous signed APK fixture, bundle rejection, new real screens. */
public final class Beta998NativeTest extends Instrumentation {
    String phase;int checks;Throwable failure;
    void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    void main(Runnable work){runOnMainSync(()->{try{work.run();}catch(Throwable t){failure=t;}});if(failure!=null){Throwable t=failure;failure=null;throw new AssertionError(t);}}
    void waitWorker()throws Exception{BetaGrowthStore.WORKER.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);waitForIdleSync();Thread.sleep(200);}
    static String text(View v){StringBuilder b=new StringBuilder();if(v instanceof TextView)b.append(((TextView)v).getText());if(v instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)v).getChildCount();i++)b.append(text(((android.view.ViewGroup)v).getChildAt(i)));return b.toString();}
    void bounds(View v){if(v==null||v.getVisibility()!=View.VISIBLE)return;if(v instanceof TextView){TextView t=(TextView)v;if(t.getLayout()!=null&&t.length()>0){android.text.Layout layout=t.getLayout();check(layout.getEllipsisCount(layout.getLineCount()-1)==0,"No truncated body text");check(t.getHeight()+1>=t.getCompoundPaddingTop()+t.getCompoundPaddingBottom()+layout.getLineBottom(layout.getLineCount()-1),"No vertically clipped body text: "+t.getText()+" height="+t.getHeight()+" needs="+(t.getCompoundPaddingTop()+t.getCompoundPaddingBottom()+layout.getLineBottom(layout.getLineCount()-1)));}if(v instanceof Button)check(v.getHeight()+1>=48*v.getResources().getDisplayMetrics().density,"48dp target");}if(v instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)v).getChildCount();i++)bounds(((android.view.ViewGroup)v).getChildAt(i));}
    @Override public void onCreate(Bundle args){super.onCreate(args);phase=args.getString("phase","verify");start();}
    @Override public void onStart(){Bundle result=new Bundle();int code=0;Context c=getTargetContext();try{
        check(Build.MODEL.contains("sdk")&&c.getPackageName().equals("dev.bennett.codexmeter.trial"),"Owned beta only");SharedPreferences qa=c.getSharedPreferences("beta998_qa",0);
        if(phase.equals("seed")){
            check(c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName.equals("9.9.7"),"Real9.9.7 installed");check(SecureTokenStore.load(c)==null,"Fresh fixture");TrialDemo.prepare(c);BetaDemo995.prepare(c);BetaUpdatePolicy.initialize(c);UpdatePreferences.setAutomaticChecks(c,false);BetaIdentity.save(c,"민수 검수 Alex");BetaIdentity.prefs(c).edit().putBoolean("setup_done",true).commit();
            String account=SubscriptionStore.accountKey(c);JSONObject state=BetaGrowthStore.load(c,account);qa.edit().putString("state",state.toString()).putString("archive",BetaGrowthStore.archive(c,account).toString()).putString("tokens",SecureTokenStore.load(c).toJson().toString()).putInt("uid",c.getApplicationInfo().uid).commit();check(state.getInt("level")>=30,"Established growth fixture");
        }else{
            check(c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName.equals("9.9.8"),"Signed9.9.8 installed");String account=SubscriptionStore.accountKey(c);JSONObject before=new JSONObject(qa.getString("state","")),state=BetaGrowthStore.load(c,account);long xp=state.getLong("total");
            check(c.getApplicationInfo().uid==qa.getInt("uid",-1),"Sandbox retained");check(SecureTokenStore.load(c).toJson().toString().equals(qa.getString("tokens","")),"Encrypted credentials preserved");
            for(String key:new String[]{"total","level","progress","days","rewards","honors","titles","equipped","enabled","cutover"})check(state.get(key).toString().equals(before.get(key).toString()),"Upgrade retains "+key);
            check(BetaGrowthStore.archive(c,account).toString().equals(qa.getString("archive","")),"Archive retained");check(BetaIdentity.name(c).equals("민수 검수 Alex"),"Name retained");qa.edit().putString("name",BetaIdentity.name(c)).commit();check(!UpdatePreferences.automaticChecks(c),"OFF retained");
            String id="";for(String[] e:BetaCatalog.ALL)if(!BetaCatalog.title(e[0])&&!state.getJSONObject("honors").has(e[0])){id=e[0];break;}
            check(BetaPreferences.pin(c,account,id),"Pin current account goal");waitWorker();check(BetaGrowthStore.peek(c).getJSONObject("next_goal").getString("id").equals(id),"Pinned goal in worker cache");check(!BetaPreferences.pin(c,"f".repeat(64),id),"Other account pin rejected");check(!BetaPreferences.pin(c,account,"custom"),"Unknown goal rejected");
            JSONObject file=BetaBundle.collect(c,account,true,true);check(!file.toString().contains("access_token")&&!file.toString().contains("refresh_token"),"Bundle excludes credentials");check(BetaBundle.preview(c,account,file,true,true).getLong("total")==xp,"Bundle preview");
            JSONObject bad=new JSONObject(file.toString()).put("account","f".repeat(64));boolean denied=false;try{BetaBundle.preview(c,account,bad,true,true);}catch(Exception expected){denied=true;}check(denied,"Foreign account bundle refused");
            bad=new JSONObject(file.toString()).put("authentication",new JSONObject());denied=false;try{BetaBundle.preview(c,account,bad,true,true);}catch(Exception expected){denied=true;}check(denied,"Unknown auth section refused");
            check(BetaBundle.restore(c,account,file,true,true).length()>0,"Bundle roundtrip reports sections");check(BetaGrowthStore.load(c,account).getLong("total")==xp,"Bundle never multiplies XP");
            check(BetaBundle.preview(c,account,BetaGrowthStore.export(c,account),true,false).getLong("total")==xp,"Legacy growth file supported");
            String oldTone=FunStore.tone(c);FunStore.tone(c,"calm");check(CoachPolicy.tone(c).equals("spicy"),"Fixed character ignores old personalization");FunStore.tone(c,"off");check(CoachPolicy.tone(c).equals("off"),"OFF respected");FunStore.tone(c,oldTone);
            c.getSystemService(android.app.LocaleManager.class).setApplicationLocales(android.os.LocaleList.forLanguageTags("ko"));Thread.sleep(400);
            for(String page:new String[]{"health","journey","recap"}){
                Activity a=startActivitySync(new Intent(c,BetaHubActivity.class).putExtra("page",page).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitWorker();main(()->{View root=a.findViewById(android.R.id.content);check(root.findViewWithTag("beta998:"+page)!=null,"Actual "+page+" screen");bounds(root);if(page.equals("recap"))check(text(root).contains("자료 부족"),"Missing usage evidence never displayed as zero");});capture(c,page);if(page.equals("recap")){IntentFilter filter=new IntentFilter(Intent.ACTION_CHOOSER);ActivityMonitor chooser=addMonitor(filter,new ActivityResult(Activity.RESULT_CANCELED,null),true);main(()->BetaRecapShare.share((BetaHubActivity)a,account,"GPT HUD · 가상 데모\n기록 회고 · 실제 성과 아님"));waitWorker();check(chooser.getHits()>0,"Actual local PNG and FileProvider chooser reached; external send intercepted");removeMonitor(chooser);}main(a::finish);
            }
            MainActivity home=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1800);waitWorker();main(()->{View root=home.findViewById(android.R.id.content);check(root.findViewWithTag("beta998:focus")!=null,"Actual home focus card");check(!text(root).contains(c.getString(R.string.coach_another)),"No manual quote replacement");});capture(c,"home");main(home::finish);
            BetaProfileActivity profile=(BetaProfileActivity)startActivitySync(new Intent(c,BetaProfileActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitWorker();check(profile.state!=null&&profile.png!=null,"Profile PNG ready");byte[] first=profile.png.clone();String oldFrame=BetaPreferences.prefs(c).getString(account+":frame","");main(profile::chooseFrame);check(profile.selection.getListView().getCount()==2,"Only default and earned Lv30 frame offered");main(()->profile.selection.getListView().performItemClick(null,1,1));waitWorker();check(BetaPreferences.prefs(c).getString(account+":frame","").equals("rpg3.frame_30"),"Owned frame chosen");check(!java.util.Arrays.equals(first,profile.png),"Frame affects actual PNG");BetaPreferences.prefs(c).edit().putString(account+":frame",oldFrame).commit();main(profile::finish);
            BetaBackupActivity backup=(BetaBackupActivity)startActivitySync(new Intent(c,BetaBackupActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
            final Bundle saved=new Bundle();main(()->{backup.account=account;backup.pendingName="12345678-1234-1234-1234-123456789abc.json";backup.onSaveInstanceState(saved);});check(saved.getString("account").equals(account)&&saved.getString("pending").endsWith(".json"),"Pending file/account survive saved state");java.io.File savedFile=backup.cached(backup.pendingName);java.nio.file.Files.write(savedFile.toPath(),file.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));
            ActivityMonitor monitor=addMonitor(BetaBackupActivity.class.getName(),null,false);main(backup::recreate);BetaBackupActivity recreated=(BetaBackupActivity)monitor.waitForActivityWithTimeout(5000);removeMonitor(monitor);check(recreated!=null,"Actual backup Activity recreated");check(recreated.account.equals(account)&&recreated.pendingName.equals(saved.getString("pending")),"Pending account/file restored after real recreation");
            java.io.File destination=new java.io.File(c.getExternalFilesDir(null),"recreated-backup.json");main(()->recreated.write(android.net.Uri.fromFile(destination)));waitWorker();check(new String(java.nio.file.Files.readAllBytes(destination.toPath()),java.nio.charset.StandardCharsets.UTF_8).equals(file.toString()),"Document callback writes original pending bytes after recreation");main(recreated::finish);
            check(BetaGrowthStore.load(c,account).getLong("total")==xp,"All new views give no XP");BetaPreferences.pin(c,account,"");
        }
        result.putString("stream","Beta998 native "+phase+": "+checks+" checks passed; synthetic only.\n");code=-1;
    }catch(Throwable error){result.putString("stream",android.util.Log.getStackTraceString(error));}finish(code,result);}
    void capture(Context c,String name)throws Exception{java.io.File folder=new java.io.File(c.getExternalFilesDir(null),"beta998-captures");folder.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(folder,name+".png"))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}
}
